    'Profaịlụ gị, post gị, reel gị, story gị, nkọwa gị na ozi ị zigara, foto na vidiyo gị, ndị na-eso gị na ndị ị na-eso, ndị enyi, gburugburu, ezigbo ndị enyi, ihe na-amasị gị na ncheta onye enyemaka. A na-ewepụ gị ebe niile ị banyere, ngwaọrụ gị na-akwụsịkwa inweta ọkwa.',
